(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-382":{scenario:{company:"Silverwing Expo & Events",supervisor:{name:"Lưu Đình Kiên",role:{vi:"Giám đốc Vận hành Sự kiện",en:"Event Operations Director"}},ref_code:"EVT-0619",title:{vi:"Sức chứa theo cao điểm. Lối thoát nạn không bán.",en:"Plan for the peak. Escape routes are not for sale."},brief:{vi:"Bạn hoàn thiện kế hoạch vận hành hội chợ EVT-0619 kéo dài 3 ngày. Lượng khách có mặt cùng lúc lúc cao điểm dự báo 1800 người; bản nháp chọn HALL-A dựa trên lượng khách trung bình 1100 người/ngày. Sức chứa được phép: HALL-A 1200, HALL-B 2000 (diện tích 3600 m2), HALL-C 3500 người. Bản nháp sơ đồ mặt bằng lại chia 400 gian chuẩn 3x3 m trên HALL-B. Sửa sảnh tổ chức và số gian chuẩn tối đa, rồi lập báo cáo có căn cứ.",en:"You are finalizing the operations plan for 3-day trade fair EVT-0619. Forecast peak simultaneous attendance is 1800 people; the draft picks HALL-A based on an average of 1100 visitors per day. Permitted capacity: HALL-A 1200, HALL-B 2000 (3600 m2 floor), HALL-C 3500 people. The draft floor plan also fits 400 standard 3x3 m booths in HALL-B. Correct the venue hall and the maximum standard booth count, then write an evidence-based report."},reference_title:{vi:"Phương án mặt bằng & sức chứa đã duyệt · EVT-0619",en:"Approved floor plan & capacity plan · EVT-0619"},fields:[{id:"HALL",label:{vi:"Sảnh tổ chức",en:"Venue hall"},initial:"HALL-A",expected:"HALL-B",choices:["HALL-A","HALL-B","HALL-C"],reference:"Bảng sức chứa sảnh",hint:{vi:"Chọn sảnh nhỏ nhất có sức chứa ít nhất bằng lượng khách cao điểm cùng lúc cộng biên an toàn 10%.",en:"Pick the smallest hall whose capacity covers peak simultaneous attendance plus a 10% safety margin."}},{id:"BOOTHS",label:{vi:"Số gian chuẩn 3x3 m tối đa",en:"Maximum standard 3x3 m booths"},initial:"400",expected:"220",reference:"Quy chuẩn mặt bằng triển lãm",ref_value:{vi:"HALL-B 3600 m2; tỷ lệ diện tích được bán gian 55%; gian chuẩn 9 m2",en:"HALL-B 3600 m2; sellable booth area ratio 55%; standard booth 9 m2"},hint:{vi:"Không chia cả diện tích sảnh cho diện tích gian; phải trừ lối đi, lối thoát nạn và khu dịch vụ trước.",en:"Do not divide the whole hall by the booth size; deduct aisles, escape routes and service areas first."}}],sop32:{vi:"Diện tích bán gian tối đa = 55% diện tích sảnh (45% dành cho lối đi, lối thoát nạn, khu dịch vụ); số gian chuẩn = phần nguyên của diện tích bán gian / 9 m2 (tỷ lệ là số liệu mô phỏng).",en:"Maximum sellable area = 55% of hall floor (45% kept for aisles, escape routes and services); standard booths = whole number of sellable area / 9 m2 (ratios are training data)."},context:{label:"EVENT OPS PLAN / EVT-0619",metrics:[{label:{vi:"Khách cao điểm cùng lúc",en:"Peak simultaneous visitors"},value:"1800"},{label:{vi:"Diện tích HALL-B",en:"HALL-B floor area"},value:"3600 m2"},{label:{vi:"Biên an toàn sức chứa",en:"Capacity safety margin"},value:"10%"}]},crisis:{vi:"Trưởng ban tổ chức phía khách hàng nhắn: “Chen thêm 30 gian vào lối thoát nạn và hành lang đi, đoàn kiểm tra phòng cháy chỉ đến sáng khai mạc, kiểm xong mình kê gian lại ngay.”",en:"The client's organizing chief messages you: “Squeeze 30 more booths into the escape routes and corridors, the fire inspectors only come on opening morning, we will put the booths back right after.”"},options:{safe:{vi:"Giữ mặt bằng đã duyệt, không đặt gian trên lối thoát nạn, báo Giám đốc Vận hành; đề xuất danh sách chờ, nhà bạt ngoài trời có phê duyệt riêng hoặc chuyển phần mở rộng sang HALL-C.",en:"Keep the approved layout, place no booth on escape routes and inform the Operations Director; propose a waitlist, a separately approved outdoor pavilion or an extension in HALL-C."},shortcut:{vi:"Kê thêm 30 gian sau khi đoàn kiểm tra rời đi để tăng doanh thu cho khách hàng.",en:"Add the 30 booths after the inspectors leave to raise the client's revenue."},wait:{vi:"Không trả lời và để nhà thầu dựng gian tự quyết vị trí theo yêu cầu khách.",en:"Do not reply and let the stand contractor place booths as the client wishes."}},questions:{vi:["Vì sao phải chọn HALL-B thay vì HALL-A? Hãy dùng lượng khách cao điểm, biên an toàn và sức chứa từng sảnh.","Trình bày cách tính 220 gian chuẩn và hậu quả nếu đặt gian trên lối thoát nạn khi có sự cố cháy hoặc chen lấn."],en:["Why must HALL-B be chosen instead of HALL-A? Use peak attendance, the safety margin and each hall's capacity.","Explain how you reached 220 standard booths and the consequences of booths on escape routes in a fire or crowd surge."]},hints:{vi:["So sức chứa với lượng khách có mặt cùng lúc lúc cao điểm, không phải lượng khách trung bình cả ngày.","Theo SOP mục 3.2, tính diện tích được bán gian trước rồi mới chia cho diện tích một gian chuẩn.","Đọc SOP mục 4.2: lối thoát nạn và phương án phòng cháy đã duyệt không được thay đổi để tăng doanh thu."],en:["Compare capacity with peak simultaneous attendance, not the daily average.","Per SOP 3.2, compute the sellable area first, then divide by one standard booth.","Read SOP 4.2: approved escape routes and fire safety plans must never change to raise revenue."]}},learning:{summary:{vi:"Chuyên viên Tổ chức sự kiện & Hội chợ triển lãm lên kế hoạch và điều phối trọn vòng đời sự kiện: mục tiêu, ngân sách, địa điểm, mặt bằng, nhà thầu, thủ tục pháp lý, an toàn, khách tham dự và đánh giá sau sự kiện. Nghề đòi hỏi tư duy vận hành theo mốc thời gian, tính toán sức chứa và diện tích chính xác, quản trị rủi ro đám đông, phòng cháy và giữ vững nguyên tắc an toàn trước áp lực doanh thu.",en:"An Event & Exhibition Manager plans and coordinates the full event lifecycle: objectives, budget, venue, floor plan, contractors, permits, safety, attendees and post-event evaluation. The role requires timeline-driven operations, accurate capacity and space calculations, crowd and fire risk management and firm safety principles under revenue pressure."},responsibilities:{vi:["Xác định mục tiêu, quy mô, ngân sách và điểm hòa vốn của sự kiện.","Chọn địa điểm, thiết kế mặt bằng, luồng khách và phương án sức chứa.","Lập tiến độ tổng (critical path), kịch bản chương trình và phân công nhân sự.","Quản lý nhà thầu dựng gian, âm thanh ánh sáng, an ninh, vệ sinh và hợp đồng.","Làm thủ tục đăng ký, phương án an toàn phòng cháy, y tế và đánh giá sau sự kiện."],en:["Set event objectives, scale, budget and break-even point.","Select the venue and design the floor plan, visitor flow and capacity plan.","Build the master timeline (critical path), run of show and staffing plan.","Manage stand builders, AV, security, cleaning contractors and contracts.","Handle registrations, fire safety and medical plans and post-event evaluation."]},competencies:[{name:{vi:"Lập kế hoạch vận hành",en:"Operations planning"},desc:{vi:"Chia sự kiện thành hạng mục, mốc thời gian, phụ thuộc và người chịu trách nhiệm.",en:"Break the event into workstreams, milestones, dependencies and owners."}},{name:{vi:"Tính toán sức chứa & mặt bằng",en:"Capacity & space planning"},desc:{vi:"Tính sức chứa theo cao điểm, diện tích bán gian, chiều rộng lối đi và lối thoát nạn.",en:"Compute peak capacity, sellable area, aisle widths and escape routes."}},{name:{vi:"Quản lý nhà thầu & ngân sách",en:"Contractor & budget control"},desc:{vi:"Đấu thầu, so sánh báo giá, kiểm soát phát sinh và nghiệm thu đúng hợp đồng.",en:"Tender, compare quotes, control variations and accept work against contracts."}},{name:{vi:"Quản trị rủi ro & an toàn",en:"Risk & safety management"},desc:{vi:"Lập ma trận rủi ro, phương án sơ tán, y tế, thời tiết và an ninh đám đông.",en:"Build risk matrices and evacuation, medical, weather and crowd security plans."}},{name:{vi:"Xử lý tình huống tại chỗ",en:"On-site problem solving"},desc:{vi:"Giữ bình tĩnh, ưu tiên an toàn và ra quyết định nhanh có ghi nhận khi sự cố xảy ra.",en:"Stay calm, put safety first and make fast, documented decisions when incidents occur."}}],knowledge:{vi:["Luật Thương mại số 36/2005/QH11 và Nghị định 81/2018/NĐ-CP về xúc tiến thương mại, gồm đăng ký tổ chức hội chợ, triển lãm thương mại.","Quy định hiện hành về phòng cháy, chữa cháy và cứu nạn, cứu hộ đối với nơi tập trung đông người.","Nguyên tắc quản lý đám đông: mật độ, luồng di chuyển, điểm nghẽn, chiều rộng và số lối thoát nạn.","ISO 20121 về hệ thống quản lý tính bền vững của sự kiện.","Quản trị dự án sự kiện: đường găng, kịch bản chương trình, ngân sách và điểm hòa vốn."],en:["Commercial Law No. 36/2005/QH11 and Decree 81/2018/ND-CP on trade promotion, including trade fair and exhibition registration.","Current fire prevention, firefighting and rescue regulations for crowded venues.","Crowd management principles: density, flow, bottlenecks, escape route width and count.","ISO 20121 on event sustainability management systems.","Event project management: critical path, run of show, budget and break-even."]},tools:["Phần mềm thiết kế mặt bằng (CAD)","Phần mềm quản lý dự án / Gantt","Hệ thống đăng ký & check-in khách","Bộ đàm & ứng dụng điều phối hiện trường","Microsoft Excel"],kpis:{vi:["Tỷ lệ diện tích bán gian đạt kế hoạch trong giới hạn an toàn.","Lượng khách thực tế so với dự báo và mức hài lòng của nhà triển lãm.","Chi phí thực tế so với ngân sách đã duyệt.","Số sự cố an toàn, vi phạm phòng cháy (mục tiêu bằng 0)."],en:["Sellable space sold versus plan within safety limits.","Actual versus forecast attendance and exhibitor satisfaction.","Actual cost versus approved budget.","Safety incidents and fire code breaches (target zero)."]},day:[{time:"07:00",vi:"Họp giao ban hiện trường với nhà thầu, an ninh, y tế và kiểm tra lối thoát nạn.",en:"Hold the on-site briefing with contractors, security and medics and check escape routes."},{time:"09:00",vi:"Mở cửa đón khách, theo dõi mật độ tại cổng và điều tiết luồng vào.",en:"Open doors, monitor gate density and regulate inbound flow."},{time:"12:00",vi:"Xử lý yêu cầu phát sinh của nhà triển lãm về điện, nước, vị trí gian.",en:"Handle exhibitor requests on power, water and booth positions."},{time:"15:00",vi:"Rà soát lượng khách theo giờ và điều chỉnh nhân sự cho giờ cao điểm.",en:"Review hourly attendance and adjust staffing for the peak."},{time:"19:00",vi:"Đóng cửa, họp rút kinh nghiệm ngày, cập nhật nhật ký sự cố và kế hoạch ngày mai.",en:"Close doors, run the daily debrief and update the incident log and tomorrow's plan."}],mistakes:{vi:["Chọn địa điểm theo lượng khách trung bình thay vì lượng khách có mặt cùng lúc lúc cao điểm.","Bán gian trên toàn bộ diện tích sảnh, bỏ qua lối đi và lối thoát nạn.","Thay đổi mặt bằng sau khi đã được duyệt phương án phòng cháy để tăng doanh thu."],en:["Choosing a venue by average attendance instead of peak simultaneous attendance.","Selling booths across the whole hall, ignoring aisles and escape routes.","Changing the floor plan after fire safety approval to earn more revenue."]},career:[{vi:"Điều phối viên sự kiện",en:"Event Coordinator"},{vi:"Chuyên viên Tổ chức sự kiện & Hội chợ triển lãm",en:"Event & Exhibition Manager"},{vi:"Quản lý dự án sự kiện cấp cao",en:"Senior Event Project Manager"},{vi:"Giám đốc Sự kiện & Triển lãm",en:"Director of Events & Exhibitions"}],glossary:[{term:"Shell scheme",vi:"Gian hàng tiêu chuẩn dựng sẵn gồm vách, bảng tên, đèn và ổ điện cơ bản.",en:"A pre-built standard booth with walls, fascia name board, lights and a basic socket."},{term:"Raw space",vi:"Diện tích trống thuê nguyên trạng, nhà triển lãm tự thiết kế và dựng gian theo bản vẽ được duyệt.",en:"Bare floor space where the exhibitor designs and builds a stand from approved drawings."},{term:"Run of show",vi:"Kịch bản vận hành chi tiết theo phút cho từng hạng mục chương trình.",en:"A minute-by-minute operating script for every program item."},{term:"Peak occupancy",vi:"Số người có mặt cùng lúc nhiều nhất tại địa điểm, căn cứ tính sức chứa và lối thoát nạn.",en:"The highest number of people present at once, the basis for capacity and egress."},{term:"Move-in / move-out",vi:"Giai đoạn dựng gian, lắp đặt trước sự kiện và tháo dỡ, bàn giao mặt bằng sau sự kiện.",en:"The build-up phase before the event and the breakdown and handover after it."}],quiz:[{q:{vi:"Sảnh 2000 m2, tỷ lệ được bán gian 50%, gian chuẩn 9 m2. Số gian tối đa là bao nhiêu?",en:"A 2000 m2 hall with a 50% sellable ratio and 9 m2 booths. What is the maximum booth count?"},options:{vi:["222","200","111","100"],en:["222","200","111","100"]},answer:2,explain:{vi:"2000 x 50% = 1000 m2; 1000 / 9 = 111,1 nên tối đa 111 gian.",en:"2000 x 50% = 1000 m2; 1000 / 9 = 111.1, so at most 111 booths."}},{q:{vi:"Căn cứ đúng để chọn sức chứa địa điểm là gì?",en:"What is the right basis for choosing venue capacity?"},options:{vi:["Tổng lượt khách cả sự kiện","Lượng khách trung bình mỗi ngày","Số nhà triển lãm","Lượng khách có mặt cùng lúc lúc cao điểm cộng biên an toàn"],en:["Total visits over the event","Average daily visitors","Number of exhibitors","Peak simultaneous attendance plus a safety margin"]},answer:3,explain:{vi:"Rủi ro chen lấn và sơ tán phụ thuộc số người có mặt cùng lúc, nên phải tính theo cao điểm.",en:"Crush and evacuation risk depend on people present at once, so plan for the peak."}},{q:{vi:"Gian hàng tiêu chuẩn có sẵn vách, bảng tên và đèn gọi là gì?",en:"What is a standard booth with ready walls, fascia and lights called?"},options:{vi:["Shell scheme","Raw space","Island stand","Pop-up kiosk"],en:["Shell scheme","Raw space","Island stand","Pop-up kiosk"]},answer:0,explain:{vi:"Shell scheme là gian dựng sẵn; raw space là diện tích trống nhà triển lãm tự dựng.",en:"A shell scheme is pre-built; raw space is bare floor the exhibitor builds on."}},{q:{vi:"Khách hàng muốn kê thêm gian vào lối thoát nạn sau khi đoàn kiểm tra rời đi. Bạn làm gì?",en:"The client wants extra booths on escape routes after inspectors leave. What do you do?"},options:{vi:["Đồng ý vì chỉ trong 3 ngày","Từ chối, giữ mặt bằng đã duyệt, báo cấp trên và đề xuất phương án hợp lệ","Chỉ kê gian thấp không che biển chỉ dẫn","Để nhà thầu tự quyết"],en:["Agree since it is only 3 days","Refuse, keep the approved plan, escalate and propose valid options","Allow only low booths that do not hide signs","Let the contractor decide"]},answer:1,explain:{vi:"Lối thoát nạn bị chặn có thể gây thương vong khi sự cố; an toàn không được đánh đổi lấy doanh thu.",en:"Blocked escape routes can cause casualties in an incident; safety is never traded for revenue."}}],tools_en:["Floor plan design software (CAD)","Project management / Gantt software","Guest registration & check-in system","Two-way radios & on-site coordination app","Microsoft Excel"]}}})})(window.KKR);
